MATCH (p:Politician)
WHERE (
      (p)-[:holdsPosition]->(:Position {name: "Prime Minister of Cambodia"})
   OR (p)-[:memberOf]->(:PoliticalParty {name: "Khmer Renovation Party"})
  )
  AND NOT EXISTS {
    MATCH (p)-[:memberOf]->(:PoliticalParty {name: "Communist Party of Kampuchea"})
  }
  AND NOT EXISTS {
    MATCH (p)-[:holdsPosition]->(hp:Position)
    WHERE hp.name CONTAINS "Head of State" OR hp.name CONTAINS "President" OR hp.name CONTAINS "Chairman"
  }
RETURN DISTINCT p.name AS politicianName;

MATCH (p:PoliticalParty)
WHERE EXISTS {
  MATCH (m:Politician)-[:memberOf]->(p)
  WHERE m.name IN ["François Mitterrand", "Guy Malandain"]
}
RETURN DISTINCT p.name AS partyName
